fn apply_command(
    doc: &mut TimelineDocument,
    command: &TimelineAuthoringCommand,
) -> Result<(), TimelineAuthoringError> {
    match command {
        TimelineAuthoringCommand::SetDocumentDuration { duration } => {
            doc.duration = *duration;
        }
        TimelineAuthoringCommand::SetDisplayRate { display_rate } => {
            doc.display_rate = *display_rate;
        }
        TimelineAuthoringCommand::RenameDocument { name } => {
            doc.name = name.clone();
        }
        TimelineAuthoringCommand::AddTrack(track) => doc.tracks.push(track.clone()),
        TimelineAuthoringCommand::RemoveTrack(id) => {
            let before = doc.tracks.len();
            doc.tracks.retain(|value| &value.id != id);
            if before == doc.tracks.len() {
                return Err(TimelineAuthoringError::MissingTarget(id.to_string()));
            }
        }
        TimelineAuthoringCommand::RenameTrack { track, name } => {
            find_track_mut(doc, track)?.name = name.clone();
        }
        TimelineAuthoringCommand::SetBinding { track, binding } => {
            find_track_mut(doc, track)?.binding = binding.clone();
        }
        TimelineAuthoringCommand::SetTrackEnabled { track, enabled } => {
            find_track_mut(doc, track)?.enabled = *enabled;
        }
        TimelineAuthoringCommand::SetTrackPriority { track, priority } => {
            find_track_mut(doc, track)?.priority = *priority;
        }
        TimelineAuthoringCommand::AddClip { track, clip } => {
            find_track_mut(doc, track)?.clips.push(clip.clone());
        }
        TimelineAuthoringCommand::RemoveClip(id) => {
            let mut found = false;
            for track in &mut doc.tracks {
                let before = track.clips.len();
                track.clips.retain(|value| &value.id != id);
                found |= before != track.clips.len();
            }
            if !found {
                return Err(TimelineAuthoringError::MissingTarget(id.to_string()));
            }
        }
        TimelineAuthoringCommand::DuplicateClip {
            clip,
            duplicate,
            start,
        } => {
            let mut source = None;
            for (track_index, track) in doc.tracks.iter().enumerate() {
                if let Some(item) = track.clips.iter().find(|item| &item.id == clip) {
                    source = Some((track_index, item.clone()));
                    break;
                }
            }
            let (track_index, mut duplicated) = source
                .ok_or_else(|| TimelineAuthoringError::MissingTarget(clip.to_string()))?;
            duplicated.id = duplicate.clone();
            duplicated.start = *start;
            doc.tracks[track_index].clips.push(duplicated);
        }
        TimelineAuthoringCommand::RenameClip { clip, name } => {
            find_clip_mut(doc, clip)?.name = name.clone();
        }
        TimelineAuthoringCommand::MoveClip { clip, start } => {
            find_clip_mut(doc, clip)?.start = *start;
        }
        TimelineAuthoringCommand::ResizeClip { clip, duration } => {
            find_clip_mut(doc, clip)?.duration = *duration;
        }
        TimelineAuthoringCommand::SetClipSourceOffset {
            clip,
            source_offset,
        } => {
            find_clip_mut(doc, clip)?.source_offset = *source_offset;
        }
        TimelineAuthoringCommand::SetClipBlend { clip, blend } => {
            find_clip_mut(doc, clip)?.blend = *blend;
        }
        TimelineAuthoringCommand::SetClipPayload { clip, payload } => {
            find_clip_mut(doc, clip)?.payload = payload.clone();
        }
        TimelineAuthoringCommand::SetPropertyKey { clip, key } => {
            let item = find_clip_mut(doc, clip)?;
            let TimelineClipPayload::TransformProperty { keys, .. } = &mut item.payload else {
                return Err(TimelineAuthoringError::Invalid(vec![TimelineDiagnostic {
                    severity: TimelineDiagnosticSeverity::Error,
                    code: "timeline.clip.not_transform_property",
                    target: clip.to_string(),
                    message: "property keys can only be edited on a Transform/Property clip".into(),
                }]));
            };
            if let Some(existing) = keys.iter_mut().find(|candidate| candidate.tick == key.tick) {
                *existing = key.clone();
            } else {
                keys.push(key.clone());
                keys.sort_by_key(|candidate| candidate.tick);
            }
        }
        TimelineAuthoringCommand::RemovePropertyKey { clip, tick } => {
            let item = find_clip_mut(doc, clip)?;
            let TimelineClipPayload::TransformProperty { keys, .. } = &mut item.payload else {
                return Err(TimelineAuthoringError::Invalid(vec![TimelineDiagnostic {
                    severity: TimelineDiagnosticSeverity::Error,
                    code: "timeline.clip.not_transform_property",
                    target: clip.to_string(),
                    message: "property keys can only be edited on a Transform/Property clip".into(),
                }]));
            };
            let before = keys.len();
            keys.retain(|candidate| candidate.tick != *tick);
            if before == keys.len() {
                return Err(TimelineAuthoringError::MissingTarget(format!(
                    "{}@{}",
                    clip, tick
                )));
            }
        }
        TimelineAuthoringCommand::AddMarker(marker) => doc.markers.push(marker.clone()),
        TimelineAuthoringCommand::RemoveMarker(id) => {
            let before = doc.markers.len();
            doc.markers.retain(|marker| &marker.id != id);
            if before == doc.markers.len() {
                return Err(TimelineAuthoringError::MissingTarget(id.to_string()));
            }
        }
        TimelineAuthoringCommand::RenameMarker { marker, name } => {
            find_marker_mut(doc, marker)?.name = name.clone();
        }
        TimelineAuthoringCommand::MoveMarker { marker, tick } => {
            find_marker_mut(doc, marker)?.tick = *tick;
        }
        TimelineAuthoringCommand::SetMarkerEvent { marker, event } => {
            find_marker_mut(doc, marker)?.event = event.clone();
        }
    }
    Ok(())
}
